mapper.select:
SELECT mn.*,
sc.c_name AS cName,
pp.p_name AS pName,
cc.con_name AS conName
FROM sign_safety_respon mn
LEFT JOIN pre_project pp ON mn.p_Id = pp.p_id
LEFT JOIN Con_Contract cc ON mn.con_Id = cc.con_id
LEFT JOIN Sys_company sc ON mn.company_Id = sc.c_id

    mn.deleted = 0
    
        AND mn.sa_Id = #{params.saId}
    
    
        AND mn.rep_person_Id = #{params.repPersonId}
    
    
        AND mn.p_Id = #{params.pId}
    
    
        AND mn.con_Id = #{params.conId}
    
    
        AND mn.company_Id = #{params.companyId}
    
    
        AND mn.sa_Name LIKE CONCAT('%', #{params.saName}, '%')
    
    
        AND mn.sa_Post LIKE CONCAT('%', #{params.saPost}, '%')
    
    
        AND mn.State = #{params.state}
    
    
        AND mn.Create_Uid = #{params.createUid}
    
    
        AND mn.Create_Uname LIKE CONCAT('%', #{params.createUname}, '%')
    
    
        AND pp.p_name LIKE CONCAT('%', #{params.pName}, '%')
    
    
        AND cc.con_name LIKE CONCAT('%', #{params.conName}, '%')
    
    
        AND sc.c_name LIKE CONCAT('%', #{params.cName}, '%')
    
    
        AND mn.sa_Sign_Time >= #{params.saSignTimeStart}
    
    
        AND mn.sa_Sign_Time <= #{params.saSignTimeEnd}
    
    
        AND mn.Create_Time >= #{params.createTimeStart}
    
    
        AND mn.Create_Time <= #{params.createTimeEnd}
    

ORDER BY mn.Create_Time DESC
